#ifndef SPHERICAL_MATH_H
#define SPHERICAL_MATH_H

#include <glm/glm.hpp>
#include <glm/gtc/constants.hpp>
#include <cmath>
#include <algorithm>
#include <string>
#include <iostream>

namespace SphericalMath {

// Clamp helper
inline float clampf(float val, float minVal, float maxVal) {
    return std::max(minVal, std::min(maxVal, val));
}

// Great-circle distance (angle in radians between two unit vectors)
inline float greatCircleDistance(const glm::vec3& u, const glm::vec3& v) {
    float dot = clampf(glm::dot(u, v), -1.0f, 1.0f);
    return std::acos(dot);
}

// Spherical Linear Interpolation (SLERP) between two unit vectors
inline glm::vec3 slerp(const glm::vec3& a, const glm::vec3& b, float t) {
    float dot = clampf(glm::dot(a, b), -1.0f, 1.0f);
    float theta = std::acos(dot);
    if (std::abs(theta) < 1e-5f) {
        return glm::normalize(glm::mix(a, b, t));
    }
    float sinTheta = std::sin(theta);
    float w1 = std::sin((1.0f - t) * theta) / sinTheta;
    float w2 = std::sin(t * theta) / sinTheta;
    return glm::normalize(w1 * a + w2 * b);
}

// Compute interior angle at vertex A between geodesic arcs AB and AC
// Uses tangent vectors on sphere surface at A
inline float computeInteriorAngle(const glm::vec3& a, const glm::vec3& b, const glm::vec3& c) {
    // Tangent along arc AB at A: component of B orthogonal to A
    glm::vec3 tAB = b - glm::dot(a, b) * a;
    // Tangent along arc AC at A: component of C orthogonal to A
    glm::vec3 tAC = c - glm::dot(a, c) * a;

    float lenAB = glm::length(tAB);
    float lenAC = glm::length(tAC);
    if (lenAB < 1e-6f || lenAC < 1e-6f) {
        return 0.0f;
    }
    tAB /= lenAB;
    tAC /= lenAC;

    float dot = clampf(glm::dot(tAB, tAC), -1.0f, 1.0f);
    return std::acos(dot);
}

// Structure holding spherical triangle geometric measurements
struct SphericalTriangleData {
    glm::vec3 A, B, C;
    float angleA_rad, angleB_rad, angleC_rad;
    float angleA_deg, angleB_deg, angleC_deg;
    float excess_rad;       // Spherical excess E = A + B + C - PI
    float area;             // Area on unit sphere = E * R^2 = E
    float arcAB_rad, arcBC_rad, arcCA_rad; // Side lengths
};

// Compute all spherical measurements for vertices A, B, C on unit sphere
inline SphericalTriangleData computeTriangle(glm::vec3 A, glm::vec3 B, glm::vec3 C) {
    A = glm::normalize(A);
    B = glm::normalize(B);
    C = glm::normalize(C);

    SphericalTriangleData data;
    data.A = A;
    data.B = B;
    data.C = C;

    data.angleA_rad = computeInteriorAngle(A, B, C);
    data.angleB_rad = computeInteriorAngle(B, C, A);
    data.angleC_rad = computeInteriorAngle(C, A, B);

    const float rad2deg = 180.0f / glm::pi<float>();
    data.angleA_deg = data.angleA_rad * rad2deg;
    data.angleB_deg = data.angleB_rad * rad2deg;
    data.angleC_deg = data.angleC_rad * rad2deg;

    data.excess_rad = data.angleA_rad + data.angleB_rad + data.angleC_rad - glm::pi<float>();
    data.area = std::max(0.0f, data.excess_rad);

    data.arcAB_rad = greatCircleDistance(A, B);
    data.arcBC_rad = greatCircleDistance(B, C);
    data.arcCA_rad = greatCircleDistance(C, A);

    return data;
}

// Input validation: check for collinearity, antipodal points, or coincident points
inline bool validatePoints(const glm::vec3& A, const glm::vec3& B, const glm::vec3& C, std::string& errorMsg) {
    // Check coincident
    if (glm::distance(A, B) < 1e-3f || glm::distance(B, C) < 1e-3f || glm::distance(C, A) < 1e-3f) {
        errorMsg = "Degenerate Input: Two or more selected points are identical/coincident.";
        return false;
    }
    // Check antipodal points
    if (glm::dot(A, B) < -0.999f || glm::dot(B, C) < -0.999f || glm::dot(C, A) < -0.999f) {
        errorMsg = "Degenerate Input: Points contain antipodal pairs (great circle is ill-defined).";
        return false;
    }
    // Check collinearity (coplanar with center of sphere)
    glm::vec3 normal = glm::cross(B - A, C - A);
    float scalarTripleProduct = std::abs(glm::dot(A, glm::cross(B, C)));
    if (scalarTripleProduct < 1e-4f || glm::length(normal) < 1e-4f) {
        errorMsg = "Degenerate Input: Selected points are collinear / lie on the same great circle.";
        return false;
    }
    return true;
}

} // namespace SphericalMath

#endif // SPHERICAL_MATH_H

#ifndef CAMERA_H
#define CAMERA_H

#include <glm/glm.hpp>
#include <glm/gtc/matrix_transform.hpp>
#include <algorithm>

class Camera {
public:
    Camera(glm::vec3 target = glm::vec3(0.0f), float distance = 2.8f, float yaw = 45.0f, float pitch = 30.0f)
        : m_target(target), m_distance(distance), m_yaw(yaw), m_pitch(pitch),
          m_defaultDistance(distance), m_defaultYaw(yaw), m_defaultPitch(pitch) {
        updateCameraVectors();
    }

    glm::mat4 getViewMatrix() const {
        return glm::lookAt(m_position, m_target, m_up);
    }

    glm::mat4 getProjectionMatrix(float aspectRatio) const {
        return glm::perspective(glm::radians(m_fov), aspectRatio, 0.1f, 100.0f);
    }

    glm::vec3 getPosition() const {
        return m_position;
    }

    float getFOV() const {
        return m_fov;
    }

    void processMouseMovement(float xoffset, float yoffset, bool constrainPitch = true) {
        float sensitivity = 0.25f;
        xoffset *= sensitivity;
        yoffset *= sensitivity;

        m_yaw += xoffset;
        m_pitch += yoffset;

        if (constrainPitch) {
            m_pitch = std::max(-89.0f, std::min(89.0f, m_pitch));
        }

        updateCameraVectors();
    }

    void processMouseScroll(float yoffset) {
        m_distance -= yoffset * 0.2f;
        m_distance = std::max(1.2f, std::min(10.0f, m_distance));
        updateCameraVectors();
    }

    void reset() {
        m_distance = m_defaultDistance;
        m_yaw = m_defaultYaw;
        m_pitch = m_defaultPitch;
        m_fov = 45.0f;
        updateCameraVectors();
    }

private:
    void updateCameraVectors() {
        float radYaw = glm::radians(m_yaw);
        float radPitch = glm::radians(m_pitch);

        glm::vec3 offset;
        offset.x = m_distance * std::cos(radPitch) * std::sin(radYaw);
        offset.y = m_distance * std::sin(radPitch);
        offset.z = m_distance * std::cos(radPitch) * std::cos(radYaw);

        m_position = m_target + offset;
        m_up = glm::vec3(0.0f, 1.0f, 0.0f);
    }

    glm::vec3 m_position;
    glm::vec3 m_target;
    glm::vec3 m_up;
    float m_distance;
    float m_yaw;
    float m_pitch;
    float m_fov = 45.0f;

    float m_defaultDistance;
    float m_defaultYaw;
    float m_defaultPitch;
};

#endif // CAMERA_H

#ifndef SPHERICAL_MESH_H
#define SPHERICAL_MESH_H

#include "glad.h"
#include <glm/glm.hpp>
#include <vector>
#include <unordered_map>
#include <cstdint>

struct Vertex {
    glm::vec3 pos;
    glm::vec3 normal;
};

class SphericalMesh {
public:
    SphericalMesh();
    ~SphericalMesh();

    // Rebuild mesh from 3 vertices on unit sphere with given subdivision depth
    void build(const glm::vec3& A, const glm::vec3& B, const glm::vec3& C, int depth);

    // Draw the surface using glDrawElements (indexed drawing)
    void render() const;

    size_t getVertexCount() const { return m_vertices.size(); }
    size_t getTriangleCount() const { return m_indices.size() / 3; }
    int getSubdivisionDepth() const { return m_depth; }

private:
    unsigned int getOrCreateMidpoint(unsigned int i1, unsigned int i2,
                                     std::unordered_map<uint64_t, unsigned int>& cache);

    void setupGLBuffers();
    void freeGLBuffers();

    int m_depth = 5;
    std::vector<Vertex> m_vertices;
    std::vector<unsigned int> m_indices;

    unsigned int m_VAO = 0;
    unsigned int m_VBO = 0;
    unsigned int m_EBO = 0;
};

#endif // SPHERICAL_MESH_H

#include "SphericalMesh.h"
#include <algorithm>
#include <cstddef>

SphericalMesh::SphericalMesh() {
}

SphericalMesh::~SphericalMesh() {
    freeGLBuffers();
}

unsigned int SphericalMesh::getOrCreateMidpoint(unsigned int i1, unsigned int i2,
                                                std::unordered_map<uint64_t, unsigned int>& cache) {
    uint32_t minIdx = std::min(i1, i2);
    uint32_t maxIdx = std::max(i1, i2);
    uint64_t key = (static_cast<uint64_t>(minIdx) << 32) | static_cast<uint64_t>(maxIdx);

    auto it = cache.find(key);
    if (it != cache.end()) {
        return it->second;
    }

    // Midpoint projected onto unit sphere
    glm::vec3 p1 = m_vertices[i1].pos;
    glm::vec3 p2 = m_vertices[i2].pos;
    glm::vec3 midpoint = glm::normalize(p1 + p2);

    Vertex v;
    v.pos = midpoint;
    v.normal = midpoint; // For unit sphere centered at origin, normal = normalized position

    unsigned int newIndex = static_cast<unsigned int>(m_vertices.size());
    m_vertices.push_back(v);
    cache[key] = newIndex;

    return newIndex;
}

void SphericalMesh::build(const glm::vec3& A, const glm::vec3& B, const glm::vec3& C, int depth) {
    m_depth = std::max(0, std::min(7, depth));
    m_vertices.clear();
    m_indices.clear();

    // Initial 3 vertices
    glm::vec3 uA = glm::normalize(A);
    glm::vec3 uB = glm::normalize(B);
    glm::vec3 uC = glm::normalize(C);

    Vertex v0 = { uA, uA };
    Vertex v1 = { uB, uB };
    Vertex v2 = { uC, uC };

    m_vertices.push_back(v0);
    m_vertices.push_back(v1);
    m_vertices.push_back(v2);

    // Initial triangle indices
    std::vector<unsigned int> currentTriangles = { 0, 1, 2 };

    // Edge midpoint cache across all triangles to avoid duplicated vertices
    std::unordered_map<uint64_t, unsigned int> midpointCache;

    // Recursive subdivision
    for (int d = 0; d < m_depth; ++d) {
        std::vector<unsigned int> nextTriangles;
        nextTriangles.reserve(currentTriangles.size() * 4);

        for (size_t i = 0; i < currentTriangles.size(); i += 3) {
            unsigned int i0 = currentTriangles[i];
            unsigned int i1 = currentTriangles[i + 1];
            unsigned int i2 = currentTriangles[i + 2];

            unsigned int m01 = getOrCreateMidpoint(i0, i1, midpointCache);
            unsigned int m12 = getOrCreateMidpoint(i1, i2, midpointCache);
            unsigned int m20 = getOrCreateMidpoint(i2, i0, midpointCache);

            // 4 sub-triangles
            // 1) Corner 0
            nextTriangles.push_back(i0);
            nextTriangles.push_back(m01);
            nextTriangles.push_back(m20);

            // 2) Corner 1
            nextTriangles.push_back(i1);
            nextTriangles.push_back(m12);
            nextTriangles.push_back(m01);

            // 3) Corner 2
            nextTriangles.push_back(i2);
            nextTriangles.push_back(m20);
            nextTriangles.push_back(m12);

            // 4) Center
            nextTriangles.push_back(m01);
            nextTriangles.push_back(m12);
            nextTriangles.push_back(m20);
        }

        currentTriangles = std::move(nextTriangles);
    }

    m_indices = std::move(currentTriangles);
    setupGLBuffers();
}

void SphericalMesh::setupGLBuffers() {
    if (m_VAO == 0) {
        glGenVertexArrays(1, &m_VAO);
        glGenBuffers(1, &m_VBO);
        glGenBuffers(1, &m_EBO);
    }

    glBindVertexArray(m_VAO);

    // VBO
    glBindBuffer(GL_ARRAY_BUFFER, m_VBO);
    glBufferData(GL_ARRAY_BUFFER, m_vertices.size() * sizeof(Vertex), m_vertices.data(), GL_DYNAMIC_DRAW);

    // EBO
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, m_EBO);
    glBufferData(GL_ELEMENT_ARRAY_BUFFER, m_indices.size() * sizeof(unsigned int), m_indices.data(), GL_DYNAMIC_DRAW);

    // Attribute 0: Position
    glEnableVertexAttribArray(0);
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, sizeof(Vertex), (void*)offsetof(Vertex, pos));

    // Attribute 1: Normal
    glEnableVertexAttribArray(1);
    glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, sizeof(Vertex), (void*)offsetof(Vertex, normal));

    glBindVertexArray(0);
}

void SphericalMesh::freeGLBuffers() {
    if (m_VAO != 0) {
        glDeleteVertexArrays(1, &m_VAO);
        glDeleteBuffers(1, &m_VBO);
        glDeleteBuffers(1, &m_EBO);
        m_VAO = m_VBO = m_EBO = 0;
    }
}

void SphericalMesh::render() const {
    if (m_VAO != 0 && !m_indices.empty()) {
        glBindVertexArray(m_VAO);
        glDrawElements(GL_TRIANGLES, static_cast<GLsizei>(m_indices.size()), GL_UNSIGNED_INT, 0);
        glBindVertexArray(0);
    }
}

#ifndef GEODESIC_EDGES_H
#define GEODESIC_EDGES_H

#include "glad.h"
#include <glm/glm.hpp>
#include <vector>

class GeodesicEdges {
public:
    GeodesicEdges();
    ~GeodesicEdges();

    // Rebuild the 3 great-circle arcs between A, B, and C
    void build(const glm::vec3& A, const glm::vec3& B, const glm::vec3& C, int samplesPerArc = 120);

    // Render edge 0 (A->B, Red), edge 1 (B->C, Green), edge 2 (C->A, Gold)
    void render(unsigned int shaderProgram, int edgeIndex) const;

    glm::vec3 getEdgeColor(int edgeIndex) const {
        if (edgeIndex == 0) return glm::vec3(0.95f, 0.25f, 0.25f); // Red
        if (edgeIndex == 1) return glm::vec3(0.25f, 0.85f, 0.25f); // Green
        return glm::vec3(0.98f, 0.82f, 0.15f);                     // Gold/Yellow
    }

private:
    void setupArc(int index, const glm::vec3& start, const glm::vec3& end, int samples);
    void freeGLBuffers();

    unsigned int m_VAO[3] = {0, 0, 0};
    unsigned int m_VBO[3] = {0, 0, 0};
    int m_vertexCount[3] = {0, 0, 0};
};

#endif // GEODESIC_EDGES_H

#include "GeodesicEdges.h"
#include "SphericalMath.h"

GeodesicEdges::GeodesicEdges() {
}

GeodesicEdges::~GeodesicEdges() {
    freeGLBuffers();
}

void GeodesicEdges::freeGLBuffers() {
    for (int i = 0; i < 3; ++i) {
        if (m_VAO[i] != 0) {
            glDeleteVertexArrays(1, &m_VAO[i]);
            glDeleteBuffers(1, &m_VBO[i]);
            m_VAO[i] = m_VBO[i] = 0;
            m_vertexCount[i] = 0;
        }
    }
}

void GeodesicEdges::setupArc(int index, const glm::vec3& start, const glm::vec3& end, int samples) {
    if (m_VAO[index] == 0) {
        glGenVertexArrays(1, &m_VAO[index]);
        glGenBuffers(1, &m_VBO[index]);
    }

    std::vector<glm::vec3> points;
    points.reserve(samples + 1);

    glm::vec3 uStart = glm::normalize(start);
    glm::vec3 uEnd = glm::normalize(end);

    for (int i = 0; i <= samples; ++i) {
        float t = static_cast<float>(i) / static_cast<float>(samples);
        glm::vec3 p = SphericalMath::slerp(uStart, uEnd, t);
        // Slight radial offset (1.002) to guarantee clean visibility over surface without z-fighting
        points.push_back(p * 1.002f);
    }

    m_vertexCount[index] = static_cast<int>(points.size());

    glBindVertexArray(m_VAO[index]);
    glBindBuffer(GL_ARRAY_BUFFER, m_VBO[index]);
    glBufferData(GL_ARRAY_BUFFER, points.size() * sizeof(glm::vec3), points.data(), GL_DYNAMIC_DRAW);

    glEnableVertexAttribArray(0);
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, sizeof(glm::vec3), (void*)0);

    glBindVertexArray(0);
}

void GeodesicEdges::build(const glm::vec3& A, const glm::vec3& B, const glm::vec3& C, int samplesPerArc) {
    setupArc(0, A, B, samplesPerArc); // Edge AB
    setupArc(1, B, C, samplesPerArc); // Edge BC
    setupArc(2, C, A, samplesPerArc); // Edge CA
}

void GeodesicEdges::render(unsigned int shaderProgram, int edgeIndex) const {
    if (edgeIndex < 0 || edgeIndex > 2 || m_VAO[edgeIndex] == 0) return;

    GLint colorLoc = glGetUniformLocation(shaderProgram, "lineColor");
    glm::vec3 col = getEdgeColor(edgeIndex);
    glUniform3f(colorLoc, col.r, col.g, col.b);

    glBindVertexArray(m_VAO[edgeIndex]);
    glDrawArrays(GL_LINE_STRIP, 0, m_vertexCount[edgeIndex]);
    glBindVertexArray(0);
}

