    if (m_cubeVAO) { glDeleteVertexArrays(1, &m_cubeVAO); glDeleteBuffers(1, &m_cubeVBO); glDeleteBuffers(1, &m_cubeEBO); m_cubeVAO = m_cubeVBO = m_cubeEBO = 0; }
