void SceneRenderer::setupAxes() {
    // 3 lines extending along positive and negative axes (or origin to 1.6)
    float len = 1.6f;
    std::vector<glm::vec3> axesLines = {
        glm::vec3(0.0f, 0.0f, 0.0f), glm::vec3(len, 0.0f, 0.0f), // X
        glm::vec3(0.0f, 0.0f, 0.0f), glm::vec3(0.0f, len, 0.0f), // Y
        glm::vec3(0.0f, 0.0f, 0.0f), glm::vec3(0.0f, 0.0f, len)  // Z
    };

    glGenVertexArrays(1, &m_axesVAO);
    glGenBuffers(1, &m_axesVBO);

    glBindVertexArray(m_axesVAO);
    glBindBuffer(GL_ARRAY_BUFFER, m_axesVBO);
    glBufferData(GL_ARRAY_BUFFER, axesLines.size() * sizeof(glm::vec3), axesLines.data(), GL_STATIC_DRAW);

    glEnableVertexAttribArray(0);
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, sizeof(glm::vec3), (void*)0);
    glBindVertexArray(0);
}

void SceneRenderer::setupSphereGrid() {
    // Generate great-circle rings and latitude/longitude rings
    std::vector<glm::vec3> gridLines;
    const int segments = 72;
    const float twoPi = glm::two_pi<float>();

    auto addCircle = [&](const glm::vec3& center, float radius, const glm::vec3& normal) {
        glm::vec3 u = (std::abs(normal.z) < 0.999f) ? glm::normalize(glm::cross(normal, glm::vec3(0, 0, 1)))
                                                     : glm::normalize(glm::cross(normal, glm::vec3(1, 0, 0)));
        glm::vec3 v = glm::cross(normal, u);

        glm::vec3 prev = center + radius * (std::cos(0.0f) * u + std::sin(0.0f) * v);
        for (int i = 1; i <= segments; ++i) {
            float angle = (static_cast<float>(i) / segments) * twoPi;
            glm::vec3 curr = center + radius * (std::cos(angle) * u + std::sin(angle) * v);
            gridLines.push_back(prev);
            gridLines.push_back(curr);
            prev = curr;
        }
    };

    // 1) Major great circles (XY, YZ, ZX planes)
    addCircle(glm::vec3(0.0f), 1.0f, glm::vec3(0, 0, 1)); // Equator / XY
    addCircle(glm::vec3(0.0f), 1.0f, glm::vec3(1, 0, 0)); // Meridian / YZ
    addCircle(glm::vec3(0.0f), 1.0f, glm::vec3(0, 1, 0)); // Meridian / ZX

    // 2) Diagonal great circles (for full sphere structure)
    addCircle(glm::vec3(0.0f), 1.0f, glm::normalize(glm::vec3(1, 1, 0)));
    addCircle(glm::vec3(0.0f), 1.0f, glm::normalize(glm::vec3(1, -1, 0)));
    addCircle(glm::vec3(0.0f), 1.0f, glm::normalize(glm::vec3(0, 1, 1)));
    addCircle(glm::vec3(0.0f), 1.0f, glm::normalize(glm::vec3(0, 1, -1)));

    // 3) Latitude rings
    std::vector<float> lats = { -60.0f, -30.0f, 30.0f, 60.0f };
    for (float latDeg : lats) {
        float phi = glm::radians(latDeg);
        float r = std::cos(phi);
        float y = std::sin(phi);
        addCircle(glm::vec3(0.0f, y, 0.0f), r, glm::vec3(0, 1, 0));
    }

    m_gridVertexCount = static_cast<int>(gridLines.size());

    glGenVertexArrays(1, &m_gridVAO);
    glGenBuffers(1, &m_gridVBO);

    glBindVertexArray(m_gridVAO);
    glBindBuffer(GL_ARRAY_BUFFER, m_gridVBO);
    glBufferData(GL_ARRAY_BUFFER, gridLines.size() * sizeof(glm::vec3), gridLines.data(), GL_STATIC_DRAW);

    glEnableVertexAttribArray(0);
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, sizeof(glm::vec3), (void*)0);
    glBindVertexArray(0);
}

void SceneRenderer::setupMarkerCube() {
    // Small unit cube centered at origin
    float s = 0.022f; // half size
    struct CubeVertex { glm::vec3 pos; glm::vec3 normal; };
    std::vector<CubeVertex> vertices = {
        // Front
        { {-s, -s,  s}, {0, 0, 1} }, { { s, -s,  s}, {0, 0, 1} }, { { s,  s,  s}, {0, 0, 1} }, { {-s,  s,  s}, {0, 0, 1} },
        // Back
        { { s, -s, -s}, {0, 0, -1} }, { {-s, -s, -s}, {0, 0, -1} }, { {-s,  s, -s}, {0, 0, -1} }, { { s,  s, -s}, {0, 0, -1} },
        // Left
        { {-s, -s, -s}, {-1, 0, 0} }, { {-s, -s,  s}, {-1, 0, 0} }, { {-s,  s,  s}, {-1, 0, 0} }, { {-s,  s, -s}, {-1, 0, 0} },
        // Right
        { { s, -s,  s}, {1, 0, 0} }, { { s, -s, -s}, {1, 0, 0} }, { { s,  s, -s}, {1, 0, 0} }, { { s,  s,  s}, {1, 0, 0} },
        // Top
        { {-s,  s,  s}, {0, 1, 0} }, { { s,  s,  s}, {0, 1, 0} }, { { s,  s, -s}, {0, 1, 0} }, { {-s,  s, -s}, {0, 1, 0} },
        // Bottom
        { {-s, -s, -s}, {0, -1, 0} }, { { s, -s, -s}, {0, -1, 0} }, { { s, -s,  s}, {0, -1, 0} }, { {-s, -s,  s}, {0, -1, 0} }
    };

    std::vector<unsigned int> indices = {
        0, 1, 2,  0, 2, 3,       // Front
        4, 5, 6,  4, 6, 7,       // Back
        8, 9, 10, 8, 10, 11,     // Left
        12, 13, 14, 12, 14, 15,  // Right
        16, 17, 18, 16, 18, 19,  // Top
        20, 21, 22, 20, 22, 23   // Bottom
    };
    m_cubeIndexCount = static_cast<int>(indices.size());

    glGenVertexArrays(1, &m_cubeVAO);
    glGenBuffers(1, &m_cubeVBO);
    glGenBuffers(1, &m_cubeEBO);

    glBindVertexArray(m_cubeVAO);
    glBindBuffer(GL_ARRAY_BUFFER, m_cubeVBO);
    glBufferData(GL_ARRAY_BUFFER, vertices.size() * sizeof(CubeVertex), vertices.data(), GL_STATIC_DRAW);

    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, m_cubeEBO);
    glBufferData(GL_ELEMENT_ARRAY_BUFFER, indices.size() * sizeof(unsigned int), indices.data(), GL_STATIC_DRAW);

    glEnableVertexAttribArray(0);
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, sizeof(CubeVertex), (void*)offsetof(CubeVertex, pos));

    glEnableVertexAttribArray(1);
    glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, sizeof(CubeVertex), (void*)offsetof(CubeVertex, normal));

    glBindVertexArray(0);
}

void SceneRenderer::renderAxes(unsigned int lineShader) const {
    GLint colorLoc = glGetUniformLocation(lineShader, "lineColor");
    // Light gray / off-white axes lines
    glUniform3f(colorLoc, 0.75f, 0.75f, 0.78f);

    glBindVertexArray(m_axesVAO);
    glDrawArrays(GL_LINES, 0, 6);
    glBindVertexArray(0);
}

void SceneRenderer::renderSphereGrid(unsigned int lineShader) const {
    GLint colorLoc = glGetUniformLocation(lineShader, "lineColor");
    // Faint subtle gray grid rings
    glUniform3f(colorLoc, 0.32f, 0.34f, 0.38f);

    glBindVertexArray(m_gridVAO);
    glDrawArrays(GL_LINES, 0, m_gridVertexCount);
    glBindVertexArray(0);
}

void SceneRenderer::renderVertexMarkers(unsigned int surfaceShader, const glm::vec3& A, const glm::vec3& B, const glm::vec3& C,
                                       const glm::mat4& view, const glm::mat4& proj) const {
    GLint modelLoc = glGetUniformLocation(surfaceShader, "model");
    GLint baseColorLoc = glGetUniformLocation(surfaceShader, "objectColor");

    // White markers
    glUniform3f(baseColorLoc, 0.95f, 0.95f, 0.95f);

    glm::vec3 pts[3] = { A, B, C };
    glBindVertexArray(m_cubeVAO);

    for (int i = 0; i < 3; ++i) {
        glm::mat4 model = glm::translate(glm::mat4(1.0f), pts[i]);
        glUniformMatrix4fv(modelLoc, 1, GL_FALSE, glm::value_ptr(model));
        glDrawElements(GL_TRIANGLES, m_cubeIndexCount, GL_UNSIGNED_INT, 0);
    }

    glBindVertexArray(0);
}

#ifndef RAY_PICKER_H
#define RAY_PICKER_H

#include <glm/glm.hpp>
#include <vector>
#include <string>

class RayPicker {
public:
    RayPicker();

    // Ray-sphere intersection from mouse screen coords
    bool pickPointOnSphere(double mouseX, double mouseY, int screenWidth, int screenHeight,
                           const glm::mat4& view, const glm::mat4& proj,
                           glm::vec3& outPoint);

    // Click handling for Question 2
    // Adds a point; when 3 valid points are collected, returns true and populates outA, outB, outC
    bool registerClick(const glm::vec3& pickedPoint, glm::vec3& outA, glm::vec3& outB, glm::vec3& outC,
                       std::string& statusMessage);

    void resetClicks();
    int getClickedCount() const { return static_cast<int>(m_clickedPoints.size()); }
    const std::vector<glm::vec3>& getClickedPoints() const { return m_clickedPoints; }

private:
    std::vector<glm::vec3> m_clickedPoints;
};

#endif // RAY_PICKER_H

#include "RayPicker.h"
#include "SphericalMath.h"
#include <cmath>
#include <sstream>

RayPicker::RayPicker() {
}

bool RayPicker::pickPointOnSphere(double mouseX, double mouseY, int screenWidth, int screenHeight,
                                 const glm::mat4& view, const glm::mat4& proj,
                                 glm::vec3& outPoint) {
    if (screenWidth <= 0 || screenHeight <= 0) return false;

    // Convert mouse to NDC [-1, 1]
    float x_ndc = (2.0f * static_cast<float>(mouseX)) / screenWidth - 1.0f;
    float y_ndc = 1.0f - (2.0f * static_cast<float>(mouseY)) / screenHeight;

    glm::mat4 invVP = glm::inverse(proj * view);
    glm::vec4 nearPoint = invVP * glm::vec4(x_ndc, y_ndc, -1.0f, 1.0f);
    glm::vec4 farPoint  = invVP * glm::vec4(x_ndc, y_ndc,  1.0f, 1.0f);

    if (std::abs(nearPoint.w) < 1e-6f || std::abs(farPoint.w) < 1e-6f) return false;

    nearPoint /= nearPoint.w;
    farPoint  /= farPoint.w;

    glm::vec3 rayOrigin = glm::vec3(nearPoint);
    glm::vec3 rayDir = glm::normalize(glm::vec3(farPoint - nearPoint));

    // Intersect with unit sphere: ||rayOrigin + t*rayDir||^2 = 1.0
    float a = glm::dot(rayDir, rayDir);
    float b = 2.0f * glm::dot(rayOrigin, rayDir);
    float c = glm::dot(rayOrigin, rayOrigin) - 1.0f;

    float discriminant = b * b - 4.0f * a * c;
    if (discriminant < 0.0f) {
        return false; // Missed the sphere
    }

    float sqrtD = std::sqrt(discriminant);
    float t1 = (-b - sqrtD) / (2.0f * a);
    float t2 = (-b + sqrtD) / (2.0f * a);

    float t = -1.0f;
    if (t1 > 0.0f) t = t1;
    else if (t2 > 0.0f) t = t2;
    else return false;

    glm::vec3 hitPoint = rayOrigin + t * rayDir;
    outPoint = glm::normalize(hitPoint);
    return true;
}

bool RayPicker::registerClick(const glm::vec3& pickedPoint, glm::vec3& outA, glm::vec3& outB, glm::vec3& outC,
                              std::string& statusMessage) {
    m_clickedPoints.push_back(pickedPoint);

    if (m_clickedPoints.size() < 3) {
        std::ostringstream ss;
        ss << "Point " << m_clickedPoints.size() << " recorded: (" 
           << pickedPoint.x << ", " << pickedPoint.y << ", " << pickedPoint.z << "). Click next point.";
        statusMessage = ss.str();
        return false;
    }

    // We have 3 points: validate them
    glm::vec3 candA = m_clickedPoints[0];
    glm::vec3 candB = m_clickedPoints[1];
    glm::vec3 candC = m_clickedPoints[2];

    std::string err;
    if (!SphericalMath::validatePoints(candA, candB, candC, err)) {
        statusMessage = "REJECTED: " + err + " Resetting pick points. Please select 3 non-degenerate points.";
        m_clickedPoints.clear();
        return false;
    }

    outA = candA;
    outB = candB;
    outC = candC;
    m_clickedPoints.clear();
    statusMessage = "SUCCESS: Defined valid spherical triangle. Animating morph...";
    return true;
}

void RayPicker::resetClicks() {
    m_clickedPoints.clear();
}

#version 330 core
layout (location = 0) in vec3 aPos;
layout (location = 1) in vec3 aNormal;

out vec3 FragPos;
out vec3 Normal;

uniform mat4 model;
uniform mat4 view;
uniform mat4 projection;

void main() {
    FragPos = vec3(model * vec4(aPos, 1.0));
    Normal = mat3(transpose(inverse(model))) * aNormal;
    gl_Position = projection * view * vec4(FragPos, 1.0);
}

#version 330 core
out vec4 FragColor;

in vec3 FragPos;
in vec3 Normal;

uniform vec3 objectColor;
uniform vec3 lightColor;
uniform vec3 lightPos;
uniform vec3 viewPos;

void main() {
    // Ambient
    float ambientStrength = 0.35;
    vec3 ambient = ambientStrength * lightColor;

    // Diffuse
    vec3 norm = normalize(Normal);
    vec3 lightDir = normalize(lightPos - FragPos);
    float diff = max(dot(norm, lightDir), 0.0);
    // Two-sided soft backlighting so reverse side is also readable if viewed from behind
    float backDiff = max(dot(-norm, lightDir), 0.0) * 0.35;
    diff = max(diff, backDiff);
    vec3 diffuse = diff * lightColor;

    // Specular (Blinn-Phong)
    float specularStrength = 0.65;
    vec3 viewDir = normalize(viewPos - FragPos);
    vec3 halfwayDir = normalize(lightDir + viewDir);
    float spec = pow(max(dot(norm, halfwayDir), 0.0), 64.0);
    vec3 specular = specularStrength * spec * lightColor;

    vec3 result = (ambient + diffuse + specular) * objectColor;
    FragColor = vec4(result, 1.0);
}

